<script setup lang="ts">
import {ref,computed,onMounted,watch} from 'vue';
import {useRoute,useRouter} from 'vue-router';
import {api,labels,when} from './api';
import Icon from './Icon.vue';
import ItemEditor from './ItemEditor.vue';
import SettingsView from './SettingsView.vue';
import ShareView from './ShareView.vue';
import AiStudio from './AiStudio.vue';
import PrototypeWindow from './PrototypeWindow.vue';
const route=useRoute(),router=useRouter();
const user=ref<any>(null),ready=ref(false),login=ref({email:'',password:''}),loginError=ref(''),busy=ref(false),toast=ref(''),error=ref('');
const projects=ref<any[]>([]),items=ref<any[]>([]),activity=ref<any[]>([]),members=ref<any[]>([]),models=ref<any[]>([]),messages=ref<any[]>([]);
const projectId=ref(''),search=ref(''),filter=ref('all'),layout=ref('grid'),sidebar=ref(false);
const menuCollapsed=ref(false);
try{menuCollapsed.value=localStorage.getItem('pm-menu-collapsed')==='true';}catch{}
watch(menuCollapsed,v=>{try{localStorage.setItem('pm-menu-collapsed',String(v));}catch{}});
const editor=ref<any>(null),newProject=ref(false),projectForm=ref({name:'',description:''}),memberModal=ref(false),memberForm=ref({email:'',role:'reviewer'}),projectEdit=ref(false);
const nav=[{key:'studio',title:'AI 创作中心',icon:'Sparkles'},{key:'overview',title:'工作台',icon:'LayoutDashboard'},{key:'projects',title:'产品项目',icon:'FolderKanban'},{key:'requirements',title:'需求池',icon:'ListTodo'},{key:'documents',title:'产品文档',icon:'FileText'},{key:'prototypes',title:'原型设计',icon:'PanelsTopLeft'},{key:'templates',title:'组件模板',icon:'Blocks'},{key:'releases',title:'版本规划',icon:'GitBranch'}];
const section=computed(()=>route.path.split('/')[1]||'studio');
const current=computed(()=>projects.value.find(p=>p.id===projectId.value));
const canEdit=computed(()=>['owner','editor'].includes(current.value?.role));
const isOwner=computed(()=>current.value?.role==='owner');
const reqs=computed(()=>items.value.filter(x=>x.kind==='requirement'));
const docs=computed(()=>items.value.filter(x=>x.kind==='document'));
const prototypes=computed(()=>items.value.filter(x=>x.kind==='prototype'));
const kind=computed(():string=>({requirements:'requirement',documents:'document',prototypes:'prototype',templates:'template',releases:'release'} as any)[section.value]||'');
const filtered=computed(()=>items.value.filter(x=>x.kind===kind.value&&(!search.value||`${x.title} ${x.body.description||''}`.toLowerCase().includes(search.value.toLowerCase()))&&(filter.value==='all'||x.body.status===filter.value||x.body.type===filter.value||x.body.surface===filter.value)));
const columns=['backlog','planned','progress','review','done'];
const stats=computed(()=>[{name:'产品项目',value:projects.value.length,icon:'FolderKanban',caption:'让每个想法有序生长',color:'purple'},{name:'项目需求',value:reqs.value.length,icon:'ListTodo',caption:`${reqs.value.filter(x=>x.body.status==='done').length} 项已完成`,color:'blue'},{name:'产品文档',value:docs.value.length,icon:'FileText',caption:'沉淀团队共同的理解',color:'orange'},{name:'交互原型',value:prototypes.value.length,icon:'PanelsTopLeft',caption:'把抽象想法变得可见',color:'green'}]);
let toastTimer:any;
function notify(t:string){toast.value=t;clearTimeout(toastTimer);toastTimer=setTimeout(()=>toast.value='',4000);}
async function run(fn:()=>Promise<any>){error.value='';busy.value=true;try{return await fn();}catch(e:any){error.value=e.message;}finally{busy.value=false;}}
async function loadProjects(){projects.value=await api('/projects');if(!projects.value.some(p=>p.id===projectId.value))projectId.value=projects.value.find(p=>p.id===String(route.query.project||sessionStorage.getItem('pm-project-'+user.value?.id)||''))?.id||projects.value[0]?.id||'';}
let sequence=0;
async function loadProject(){const n=++sequence;const id=projectId.value;if(!id){items.value=[];activity.value=[];members.value=[];messages.value=[];return;}const result=await Promise.all([api(`/projects/${id}/items`),api(`/projects/${id}/activity`),api(`/projects/${id}/members`),api(`/projects/${id}/messages`)]);if(n!==sequence)return;[items.value,activity.value,members.value,messages.value]=result;}
async function refresh(){await loadProjects();await loadProject();}
async function signIn(){loginError.value='';busy.value=true;try{user.value=await api('/auth/login','POST',login.value);login.value.password='';await refresh();models.value=await api('/models');}catch(e:any){loginError.value=e.message;}finally{busy.value=false;}}
function go(key:string){router.push({path:'/'+key,query:{project:projectId.value||undefined}});sidebar.value=false;search.value='';filter.value='all';}
function createItem(k=kind.value){if(!projectId.value){newProject.value=true;return;}editor.value={kind:k,title:'',body:k==='requirement'?{status:'backlog',priority:'medium'}:k==='document'?{type:'prd'}:k==='prototype'?{language:'html',surface:'frontend'}:k==='template'?{language:'html',category:'通用组件'}:{status:'planned',requirementIds:[]}};}
function openAI(type='prd',target=''){sidebar.value=false;router.push({path:'/studio',query:{project:projectId.value,type,target:target||undefined}});}
async function saveProject(){await run(async()=>{if(projectEdit.value){await api('/projects/'+projectId.value,'PATCH',{...projectForm.value,status:current.value.status});}else{const p=await api('/projects','POST',projectForm.value);projectId.value=p.id;}newProject.value=false;projectForm.value={name:'',description:''};await refresh();notify('项目已保存');});}
async function saveMember(){await run(async()=>{await api(`/projects/${projectId.value}/members`,'POST',memberForm.value);memberForm.value={email:'',role:'reviewer'};await loadProject();notify('成员权限已保存');});}
async function logout(){await run(async()=>{await api('/auth/logout','POST',{});user.value=null;});}
async function saved(item:any){editor.value=item;await refresh();notify('已保存，版本记录已更新');}
watch(projectId,()=>{items.value=[];if(user.value&&projectId.value){sessionStorage.setItem('pm-project-'+user.value.id,projectId.value);router.replace({path:route.path,query:{...route.query,project:projectId.value,...(String(route.query.project||'')===projectId.value?{}:{target:undefined})}});}run(loadProject);});
watch(section,()=>{search.value='';filter.value='all';});
onMounted(async()=>{if(route.path.startsWith('/share/')){ready.value=true;return;}try{user.value=await api('/auth/me');await refresh();models.value=await api('/models');}catch(e:any){if(user.value)error.value=e.message;}finally{ready.value=true;}});
</script>
<template>
  <ShareView v-if="route.path.startsWith('/share/')" />
  <div v-else-if="!ready" class="boot"><Icon name="LoaderCircle" class="spin" :size="30"/><p>正在打开你的产品工作台…</p></div>
  <div v-else-if="!user" class="login-page">
    <section class="login-story"><div class="brand white"><img src="/favicon.svg" alt="序构"/><b>序构 <small>PRODUCT STUDIO</small></b></div><div class="story-content"><span class="eyebrow light">BUILT FOR PRODUCT THINKERS</span><h1>好产品，<br>从一个想法开始<span>。</span></h1><p>让 AI 参与思考，让团队达成共识。<br>从第一条需求，到每一次产品迭代。</p><div class="journey"><div><Icon name="ListTodo"/><span>理解需求</span></div><i></i><div><Icon name="PanelsTopLeft"/><span>呈现想法</span></div><i></i><div><Icon name="GitBranch"/><span>持续迭代</span></div></div></div><span class="login-foot">把复杂留给工具，把专注还给创造。</span></section>
    <section class="login-form"><div><span class="eyebrow">YOUR PRODUCT WORKSPACE</span><h2>欢迎回到序构</h2><p class="muted">登录，继续推进你的下一个好产品。</p><form @submit.prevent="signIn"><label>邮箱账号<input v-model="login.email" type="email" autocomplete="username" placeholder="输入你的邮箱" required/></label><label>登录密码<input v-model="login.password" type="password" autocomplete="current-password" placeholder="输入登录密码" required/></label><p v-if="loginError" class="error-inline" role="alert">{{loginError}}</p><button class="primary login-submit" :disabled="busy">{{busy?'正在登录…':'进入工作台'}}<Icon name="ArrowRight"/></button></form><p class="login-note"><Icon name="Lock" :size="14"/> 私有工作空间 · 仅受邀成员可访问</p></div></section>
  </div>
  <PrototypeWindow v-else-if="route.path.startsWith('/preview/')"/>
  <div v-else class="app-shell" :class="{'menu-collapsed':menuCollapsed}">
    <button v-if="sidebar" class="sidebar-backdrop" aria-label="关闭菜单" @click="sidebar=false"/><aside id="workspace-navigation" class="sidebar" :class="{mobile:sidebar}"><button class="icon-button sidebar-mobile-close" aria-label="关闭菜单" @click="sidebar=false"><Icon name="X"/></button><a class="brand" href="/" @click.prevent="go('studio')"><img src="/favicon.svg" alt="序构"/><b>序构 <small>PRODUCT STUDIO</small></b></a><button title="我的产品空间" aria-label="我的产品空间" class="workspace-select" @click="go('projects')"><span class="workspace-avatar">产</span><span><strong>我的产品空间</strong><small>{{projects.length}} 个产品项目</small></span><Icon name="ChevronDown" :size="15"/></button><div class="nav-caption">工作空间</div><nav><button v-for="n in nav" :key="n.key" :title="n.title" :aria-label="n.title" :class="{active:section===n.key}" @click="go(n.key)"><Icon :name="n.icon"/><span>{{n.title}}</span><span v-if="n.key==='requirements'" class="nav-count">{{reqs.length}}</span><small v-if="n.key==='prototypes'" class="nav-new">AI</small></button></nav><div class="sidebar-bottom"><div class="assistant-card"><span class="mini-spark"><Icon name="Sparkles" :size="17"/></span><strong>给好想法，多一点助力</strong><p>和 AI 一起，把需求变成产品。</p><button @click="openAI()">前往创作中心 <Icon name="ArrowUpRight" :size="15"/></button></div><button title="设置与集成" aria-label="设置与集成" class="settings-nav" :class="{active:section==='settings'}" @click="go('settings')"><Icon name="Settings"/><span>设置与集成</span></button><div class="profile"><span class="avatar">{{user.name.slice(0,1)}}</span><span><strong>{{user.name}}</strong><small>{{user.admin?'空间管理员':'团队成员'}}</small></span><button class="icon-button" title="退出登录" @click="logout"><Icon name="LogOut" :size="17"/></button></div></div></aside>
    <div class="main-shell"><header class="topbar"><div class="breadcrumb"><button class="icon-button mobile-toggle" :aria-label="sidebar?'折叠菜单':'展开菜单'" :aria-expanded="sidebar" aria-controls="workspace-navigation" @click="sidebar=!sidebar"><Icon name="LayoutGrid"/></button><button class="icon-button desktop-menu-toggle" :title="menuCollapsed?'展开菜单':'折叠菜单'" :aria-label="menuCollapsed?'展开菜单':'折叠菜单'" :aria-expanded="!menuCollapsed" aria-controls="workspace-navigation" @click="menuCollapsed=!menuCollapsed"><Icon :name="menuCollapsed?'PanelLeftOpen':'PanelLeftClose'"/></button><span>工作空间</span><Icon name="ChevronRight" :size="14"/><strong>{{nav.find(n=>n.key===section)?.title||'设置与集成'}}</strong></div><div class="top-actions"><span class="saved-indicator"><i></i>云端工作空间</span><button class="text-button" @click="memberModal=true" v-if="current"><Icon name="Users" :size="16"/>项目成员</button><span class="avatar small">{{user.name.slice(0,1)}}</span></div></header>
    <main>
      <div class="error-banner" v-if="error" role="alert"><Icon name="AlertCircle"/><span>{{error}}</span><button class="icon-button" @click="error=''" title="关闭"><Icon name="X"/></button></div>
      <SettingsView v-if="section==='settings'" :user="user" @notify="notify" @error="error=$event" @models="models=$event"/>
      <template v-else>
        <div v-if="section==='studio'" class="project-context studio-project-switch"><Icon name="FolderKanban" :size="16"/><select v-model="projectId" aria-label="当前产品项目"><option v-for="p in projects" :value="p.id">{{p.name}}</option></select><span class="badge">{{labels[current?.role]}}</span><button class="text-button" @click="projectEdit=false;projectForm={name:'',description:''};newProject=true"><Icon name="Plus" :size="14"/>新建项目</button></div>
        <AiStudio v-if="section==='studio'" :key="projectId" :project-id="projectId" :user-id="user.id" :project="current" :items="items" :models="models" :can-edit="canEdit" :messages="messages" @refresh="run(refresh)" @edit="editor=$event" @settings="go('settings')" @notify="notify"/>
        <template v-else>
        <div class="page-heading"><div><div class="eyebrow">{{section==='overview'?'CREATE WITH CLARITY':'PRODUCT WORKSPACE'}}</div><h1>{{section==='overview'?'让每个好想法，向前一步。':nav.find(n=>n.key===section)?.title}}</h1><p>{{({overview:'从需求到交付，你的产品创造之旅都在这里。',projects:'聚合产品上下文，让每个项目都有清晰的方向。',requirements:'收集想法、明确优先级，让每条需求都有归属。',documents:'将产品思考沉淀为清晰、可协作的团队共识。',prototypes:'让需求可见、可交互，也让讨论更具体。',templates:'把成熟设计沉淀成标准件，下一次创造更从容。',releases:'规划迭代节奏，记录每一次产品向前的脚步。'} as any)[section]}}</p></div><div class="heading-actions"><button class="secondary" @click="openAI(section==='prototypes'?'prototype':'prd')"><Icon name="Sparkles"/>AI {{section==='overview'?'产品助手':'辅助创作'}}</button><button class="primary" v-if="section==='overview'||section==='projects'" @click="projectEdit=false;projectForm={name:'',description:''};newProject=true"><Icon name="Plus"/>新建项目</button><button class="primary" v-else-if="canEdit" @click="createItem()"><Icon name="Plus"/>{{({requirements:'新建需求',documents:'新建文档',prototypes:'创建原型',templates:'创建模板',releases:'规划版本'} as any)[section]}}</button></div></div>
        <div v-if="projects.length&&section!=='projects'" class="project-context"><Icon name="FolderKanban" :size="16"/><select v-model="projectId" aria-label="当前产品项目"><option v-for="p in projects" :value="p.id">{{p.name}}</option></select><span class="context-line"></span><span>{{labels[current?.role]}}</span><span class="context-right"><Icon name="Database" :size="13"/>项目数据已连接</span></div>
        <template v-if="section==='overview'">
          <section class="hero"><div class="hero-copy"><span class="hero-label"><i></i>YOUR NEXT GREAT PRODUCT</span><h2>想法不止于想象。</h2><p>描述你的产品，让 AI 帮你梳理需求、构建原型，<br>把下一步变得更清晰。</p><button @click="openAI('prd')">从一个想法开始 <Icon name="ArrowUpRight" :size="17"/></button></div><div class="hero-art" aria-hidden="true"><div class="art-grid"></div><div class="art-line line-one"></div><div class="art-line line-two"></div><div class="art-node idea"><span class="art-icon"><Icon name="Sparkles" :size="22"/></span><div><small>THE IDEA</small><b>一个好想法</b></div></div><div class="art-node plan"><span class="art-icon"><Icon name="FileText" :size="20"/></span><div><small>THE PLAN</small><b>清晰的产品需求</b></div><Icon name="Check" class="art-check" :size="15"/></div><div class="art-node result"><span class="art-icon"><Icon name="PanelsTopLeft" :size="20"/></span><div><small>THE PRODUCT</small><b>可以体验的未来</b></div><span class="art-live"></span></div><span class="art-star">✦</span></div></section>
          <section class="stats"><article v-for="s in stats"><div><span>{{s.name}}</span><span class="stat-icon" :class="s.color"><Icon :name="s.icon"/></span></div><strong>{{s.value.toString().padStart(2,'0')}}</strong><p>{{s.caption}}</p></article></section>
          <div class="overview-columns"><section><div class="section-title"><h2>正在推进的项目 <span>{{projects.filter(p=>p.status==='active').length}}</span></h2><button class="text-button" @click="go('projects')">全部项目<Icon name="ArrowRight" :size="15"/></button></div><div class="project-grid compact"><article v-for="p in projects.filter(p=>p.status==='active').slice(0,3)" class="project-card" @click="projectId=p.id;go('requirements')" tabindex="0" @keydown.enter="projectId=p.id;go('requirements')"><div class="card-top"><span class="project-icon"><Icon name="Layers" :size="25"/></span><span class="badge green">进行中</span></div><h3>{{p.name}}</h3><p>{{p.description||'为这个产品写下目标，让协作更有方向。'}}</p><div class="project-progress"><span>需求完成度</span><b>{{p.requirements?Math.round(p.completed/p.requirements*100):0}}%</b></div><div class="progress"><i :style="{width:(p.requirements?p.completed/p.requirements*100:0)+'%'}"></i></div><div class="project-metadata"><span><Icon name="ListTodo" :size="14"/>{{p.requirements}} 需求</span><span><Icon name="PanelsTopLeft" :size="14"/>{{p.prototypes}} 原型</span><span class="right"><Icon name="Users" :size="14"/>{{p.members}}</span></div></article><button class="project-create" @click="projectEdit=false;projectForm={name:'',description:''};newProject=true"><span><Icon name="Plus" :size="24"/></span><strong>开启一个新项目</strong><p>给下一个好想法，一个专属空间</p></button></div>
          <div class="section-title spaced"><h2>值得关注的需求</h2><button class="text-button" @click="go('requirements')">查看需求池<Icon name="ArrowRight" :size="15"/></button></div><div class="focus-list"><button v-for="r in reqs.filter(x=>x.body.status!=='done').slice(0,4)" @click="editor=r"><span class="requirement-dot" :class="r.body.priority"></span><div><strong>{{r.title}}</strong><small>{{r.body.source||current?.name}}</small></div><span class="badge" :class="r.body.status">{{labels[r.body.status]}}</span><Icon name="ChevronRight" :size="16"/></button><div v-if="!reqs.length" class="empty-mini">还没有需求，从记录第一个想法开始。</div></div></section>
          <aside class="activity-panel"><div class="section-title"><h2>项目动态</h2><Icon name="Clock" :size="17"/></div><div class="timeline"><article v-for="a in activity.slice(0,6)"><span class="timeline-dot"></span><small>{{when(a.created_at)}}</small><p>{{a.action}}</p><span class="activity-author">{{a.name||'项目成员'}}</span></article><div class="empty-mini" v-if="!activity.length">项目的每一步，都会记录在这里。</div></div><div class="workflow-note"><Icon name="GitBranch"/><h4>让创造，有迹可循</h4><p>文档与原型的每一次保存，都会形成可查看的版本记录。</p><button class="text-button" @click="go('releases')">查看版本规划 <Icon name="ArrowRight" :size="14"/></button></div></aside></div>
        </template>
        <template v-else-if="section==='projects'"><div class="toolbar"><div class="search"><Icon name="Search" :size="17"/><input v-model="search" placeholder="搜索产品项目…" aria-label="搜索项目"/></div><span class="muted">{{projects.length}} 个项目</span></div><div class="project-grid"><article v-for="p in projects.filter(x=>x.name.toLowerCase().includes(search.toLowerCase()))" class="project-card"><div class="card-top"><span class="project-icon"><Icon name="FolderKanban" :size="26"/></span><span class="badge" :class="p.status==='active'?'green':''">{{labels[p.status]}}</span></div><h3>{{p.name}}</h3><p>{{p.description}}</p><div class="project-metadata"><span>{{p.requirements}} 需求</span><span>{{p.documents}} 文档</span><span>{{p.prototypes}} 原型</span></div><div class="card-footer"><span class="muted">{{when(p.updated_at)}} 更新</span><button class="text-button accent" @click="projectId=p.id;go('overview')">打开项目<Icon name="ArrowUpRight" :size="16"/></button></div><button v-if="p.role==='owner'" class="text-button" @click="projectId=p.id;projectForm={name:p.name,description:p.description};projectEdit=true;newProject=true">编辑项目信息</button></article><button class="project-create" @click="projectEdit=false;projectForm={name:'',description:''};newProject=true"><span><Icon name="Plus" :size="24"/></span><strong>新建产品项目</strong><p>开始一段新的产品旅程</p></button></div></template>
        <template v-else>
          <div class="toolbar"><div class="filter-tabs"><button :class="{selected:filter==='all'}" @click="filter='all'">全部{{({requirements:'需求',documents:'文档',prototypes:'原型',templates:'模板',releases:'版本'} as any)[section]}} <span>{{items.filter(i=>i.kind===kind).length}}</span></button><template v-if="section==='documents'"><button v-for="t in ['prd','technical','note']" :class="{selected:filter===t}" @click="filter=t">{{labels[t]}}</button></template><template v-if="section==='prototypes'"><button v-for="t in ['frontend','admin']" :class="{selected:filter===t}" @click="filter=t">{{labels[t]}}</button></template></div><div class="toolbar-right"><div class="search"><Icon name="Search" :size="16"/><input v-model="search" placeholder="搜索标题或描述…" aria-label="搜索内容"/></div><div class="view-switch" v-if="section==='requirements'"><button :class="{active:layout==='grid'}" title="看板视图" @click="layout='grid'"><Icon name="LayoutGrid" :size="16"/></button><button :class="{active:layout==='list'}" title="列表视图" @click="layout='list'"><Icon name="List" :size="16"/></button></div></div></div>
          <div v-if="section==='requirements'&&layout==='grid'" class="kanban"><section v-for="status in columns"><div class="kanban-heading"><span class="status-dot" :class="status"></span><strong>{{labels[status]}}</strong><span>{{filtered.filter(r=>r.body.status===status).length}}</span><button v-if="canEdit" class="icon-button" title="新建需求" @click="createItem();editor.body.status=status"><Icon name="Plus" :size="16"/></button></div><button class="requirement-card" v-for="r in filtered.filter(r=>r.body.status===status)" @click="editor=r"><span class="priority" :class="r.body.priority"><i></i>{{labels[r.body.priority]}}</span><h3>{{r.title}}</h3><p>{{r.body.module||'未分配模块'}}</p><footer><span>{{r.body.release||'待规划版本'}}</span><span v-if="r.body.dueDate"><Icon name="Calendar" :size="12"/>{{r.body.dueDate.slice(5)}}</span><span v-else class="avatar tiny">{{(r.body.assignee||user.name).slice(0,1)}}</span></footer></button><div class="kanban-empty" v-if="!filtered.some(r=>r.body.status===status)">暂无{{labels[status]}}需求</div></section></div>
          <div v-else-if="section==='requirements'" class="table-wrap"><table><thead><tr><th>需求</th><th>状态</th><th>优先级</th><th>版本</th><th>负责人</th><th>更新时间</th></tr></thead><tbody><tr v-for="r in filtered" tabindex="0" @click="editor=r" @keydown.enter="editor=r"><td class="title-cell">{{r.title}}</td><td><span class="badge" :class="r.body.status">{{labels[r.body.status]}}</span></td><td><span class="priority" :class="r.body.priority">{{labels[r.body.priority]}}</span></td><td>{{r.body.release||'未规划'}}</td><td>{{r.body.assignee||'未分配'}}</td><td>{{when(r.updated_at)}}</td></tr></tbody></table></div>
          <div v-else class="resource-grid"><article class="resource-card" v-for="i in filtered" @click="editor=i" tabindex="0" @keydown.enter="editor=i"><div class="resource-cover" :class="i.kind"><template v-if="i.kind==='prototype'||i.kind==='template'"><div class="mini-window"><div><i></i><i></i><i></i></div><section><aside></aside><main><span></span><span></span><div><b></b><b></b></div></main></section></div><span class="cover-language">{{labels[i.body.language]}}</span></template><template v-else><Icon :name="i.kind==='release'?'GitBranch':'FileText'" :size="42"/><span>{{i.kind==='release'?labels[i.body.status]:labels[i.body.type]}}</span></template></div><div class="resource-body"><div class="card-top"><span class="badge">{{i.kind==='prototype'?labels[i.body.surface]:i.kind==='template'?i.body.category:i.kind==='release'?'迭代规划':labels[i.body.type]}}</span><span class="muted">v{{i.version}}</span></div><h3>{{i.title}}</h3><p>{{i.body.description||i.body.source&&i.kind==='document'&&i.body.source||'持续打磨，逐步完善。'}}</p><div class="card-footer"><span>{{when(i.updated_at)}}</span><Icon name="ArrowUpRight" :size="16"/></div></div></article></div>
          <div class="empty-state" v-if="!filtered.length&&section!=='requirements'"><span><Icon :name="nav.find(n=>n.key===section)?.icon||'Box'" :size="30"/></span><h3>{{search||filter!=='all'?'没有找到匹配的内容':'这里，是下一次创造的起点'}}</h3><p>{{search?'试试其他关键词。':'创建内容或邀请 AI 参与，将项目思考沉淀在这里。'}}</p><button v-if="canEdit&&!search" class="primary" @click="createItem()"><Icon name="Plus"/>创建第一项内容</button></div>
        </template>
      </template>
      </template>
      <footer v-if="section!=='studio'" class="page-footer"><span>序构 · 让产品创造更从容</span><span>需求 · 原型 · 协作 · 交付</span></footer>
    </main></div>
    <ItemEditor v-if="editor" :key="editor.id||'new-'+editor.kind" :item="editor" :project-id="projectId" :requirements="reqs" :all-items="items" :can-edit="canEdit" :role="current?.role" @close="editor=null" @saved="saved" @error="error=$event" @notify="notify" @ai="openAI($event.kind,$event.id);editor=null"/>
    <div class="modal-backdrop" v-if="newProject" @click.self="newProject=false"><form class="modal small-modal" @submit.prevent="saveProject"><header><div><span class="eyebrow">PRODUCT PROJECT</span><h2>{{projectEdit?'编辑项目':'给好想法一个新空间'}}</h2></div><button type="button" class="icon-button" @click="newProject=false" title="关闭"><Icon name="X"/></button></header><div v-if="error" class="error-banner" role="alert">{{error}}</div><label>项目名称<input v-model="projectForm.name" required maxlength="180" placeholder="例如：客户服务工作台"/></label><label>项目目标与背景<textarea v-model="projectForm.description" rows="4" placeholder="这个产品为谁解决什么问题？" maxlength="10000"/></label><p class="muted">项目拥有独立的需求、文档、原型和成员权限。</p><footer><button type="button" class="secondary" @click="newProject=false">取消</button><button class="primary" :disabled="busy">{{busy?'保存中…':'保存项目'}}</button></footer></form></div>
    <div class="modal-backdrop" v-if="memberModal" @click.self="memberModal=false"><div class="modal small-modal"><header><div><span class="eyebrow">COLLABORATE</span><h2>项目成员</h2></div><button class="icon-button" @click="memberModal=false" title="关闭"><Icon name="X"/></button></header><div v-if="error" class="error-banner" role="alert">{{error}}</div><div v-for="m in members" class="member-row"><span class="avatar">{{m.name.slice(0,1)}}</span><div><strong>{{m.name}}</strong><small>{{m.email}}</small></div><span class="badge">{{labels[m.role]}}</span><button v-if="isOwner&&m.role!=='owner'" class="icon-button" title="移除成员" @click="run(async()=>{await api(`/projects/${projectId}/members/${m.id}`,'DELETE',{});await loadProject()})"><Icon name="X" :size="15"/></button></div><form v-if="isOwner" @submit.prevent="saveMember" class="invite-form"><h3>添加成员 / 调整权限</h3><label>成员邮箱<input v-model="memberForm.email" type="email" placeholder="输入已创建的成员账号" required/></label><label>项目权限<select v-model="memberForm.role"><option value="editor">编辑 · 可创建和修改内容</option><option value="reviewer">评审 · 可查看并提出意见</option><option value="viewer">只读 · 仅可查看</option></select></label><button class="primary" :disabled="busy">保存成员权限</button><p class="muted">新账号可由管理员在「设置与集成」中创建。</p></form></div></div>
    <div class="toast" v-if="toast" role="status"><Icon name="CheckCircle2" :size="19"/>{{toast}}</div>
  </div>
</template>
